'use strict';
(async()=>{const root=document.querySelector('#bank-verification');const token=new URLSearchParams(location.search).get('id');if(!token||!/^[A-Za-z0-9_-]{20,100}$/.test(token)){root.textContent='Identifiant de vérification invalide.';return;}try{const response=await fetch('/api/public/bank-agreements/'+encodeURIComponent(token),{credentials:'omit',cache:'no-store',redirect:'error'});if(!response.ok)throw Error('Document introuvable ou vérification indisponible.');const data=await response.json();const statuses={valid:'Signature vérifiée',expired:'Offre expirée',revoked:'Offre révoquée',unsigned:'Document non signé',invalid:'Signature ou intégrité non validée'};for(const [label,value] of [['Émetteur',data.issuer],['Document',data.id],['Date',String(data.date).slice(0,10)],['Statut',statuses[data.status]||data.status]]){const dt=document.createElement('dt'),dd=document.createElement('dd');dt.textContent=label;dd.textContent=value;root.append(dt,dd);}}catch(error){root.textContent=error.message||'Vérification indisponible.';}})();
